```ts
const { chromium } = require('playwright');

(async () => {
  // Setup
  const browser = await chromium.launch(
    { headless: false }
  );
  const context = await browser.newContext();
  const page = await context.newPage();

  await page.setContent(`<div id='should_not_leak'></div>`) 
  const locator = page.locator(`div#should_not_leak`)
  await locator.waitFor({ state: 'attached' })
  await locator.evaluate(e => e.remove())
  // make heap snapshot, there are detached DOM nodes.
})()
